-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.review_log_set_day()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  new.study_day := public.study_day_of(new.user_id, new.reviewed_at);
  return new;
end;
$function$;

grant execute on function public.review_log_set_day() to service_role;
